scwin.vScrenID = "ULDINS16000.xml";
scwin.onpageload = function() {
    scwin.gform_onload();
};
scwin.onpageunload = function() {
};

/********************************************** 
 * 함수명   : ins_search
 * 설명       : 일반 상품 조회한다.
 ***********************************************/
scwin.ins_search = function() {
    /**
     * SrM-000243255 
     */
    if (!scwin.checkSearchCondition()) {
        return false;
    }

    // 검색일 체크
    if ($c.stf.compareFromToDate2(edt_SDATE, edt_EDATE) == false) {
        return false;
    }

    // 조회 버튼 클릭 후 바로 버튼 클릭 안되게 처리 20220922
    fn_SetDisableSelectBtn(btn_search, true);
    $c.cm.ShowWin(grd_Grid); // 그리드명을 표기

    var url = "/listingCommon.do?SCREN_ID=" + scwin.vScrenID + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 + "&method=listGeneralForDynamicName" + "&outputMessageId=ULDINS16000_LIST_OUT" + "&service=krx.lds.ins.listingcommon.services.ListingCommonApp" + "&queryId=lds.ins.prod.select.listStdCdProdInfoInquiry" + "&{P}SDATE=" + edt_SDATE.getValue() + "&{P}EDATE=" + edt_EDATE.getValue() + "&{P}PROD_GRP_KOR_NM=" + $c.stf.getObjectValue(cmb_PROD_GRP_KOR_NM) + "&{P}HALT_YN=" + $c.stf.getObjectValue(cmb_HALT_YN) + "&{P}ISU_KOR_ABBRV=" + txb_pISU_KOR_ABBRV.getValue() + "&{P}ISU_CD=" + txb_pISU_CD.getValue();
    //alert(getObjectValue(cmb_pISUR_APPL_TP_CD));
    // alert(getObjectValue(cmb_pPROC));

    dts_List.DataID = encodeURI(url);
    dts_List.reset();
};


/********************************************** 
 * 함수명   : checkSearchCondition
 * 설명      : SrM-000243255  조회조건을 체크
 *                표준코드, 한글종목명, 발행기관코드에 값이 입력 안되었을 경우 
 *                날짜 조건은 필수로 입력되도록.. 날짜 입력가능 범위는 5년..
 ***********************************************/
scwin.checkSearchCondition = function() {
    var sStdCd = $c.stf.getObjectValue(txb_pISU_CD);
    var sIsuKorNm = $c.stf.getObjectValue(txb_pISU_KOR_ABBRV);
    var sSDateFrom = $c.stf.getObjectValue(edt_SDATE); //코드부여일(from)
    var sSDateTo = $c.stf.getObjectValue(edt_EDATE); //코드부여일(to)

    if (sStdCd == "" && sIsuKorNm == "") {
        if (sSDateFrom == "" && sSDateTo == "") {
            var msg = "조회조건을 최소 1개 이상 입력하세요.\n\n" + "[표준코드, 한글종목명] 중 1개 이상의 조건을 입력하거나, \n" + "[영업일]의 검색기간을 1년 이내로 입력하세요.";
            $c.win.alert(msg);
            return false;
        }

        // 코드부여일 체크
        if (sSDateFrom != "" && sSDateTo != "") {
            if (eval($c.ut.cGetPlusYear(sSDateFrom, 1)) < eval(sSDateTo)) {
                $c.win.alert("영업일의 검색기간은 1년 이내로 입력하세요.");
                edt_SDATE.focus();
                return false;
            }
        } else if (sSDateFrom != "" || sSDateTo != "") {
            $c.win.alert("영업일의 검색기간은 1년 이내로 입력하세요.");
            if (sSDateFrom == "") {
                edt_SDATE.focus();
            } else {
                edt_EDATE.focus();
            }
            return false;
        }
    }
    return true;
};
scwin.gform_onload = function() {
    //PanelToGroupBox(panel_1);
    $c.cm.PanelToGroupBox(panel_2);
    txb_pISU_CD.focus();
};
scwin.dts_List_OnLoadCompleted = function(rowcount) {
    if (dts_List.errorMsg) {
        $c.win.alert(dts_List.errorMsg);
    } else {
        txb_TotalCnt.setValue("총 " + rowcount + "건");
    }
    $c.cm.CloseWin(rowcount, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.dts_List_OnLoadError = function() {
    $c.stf.alert_error(dts_List);
    $c.cm.CloseWin(0, grd_Grid); //데이터 로딩중닫기 및 조회없음 처리	

    // 조회버튼 활성.
    fn_SetDisableSelectBtn(btn_search, false);
};
scwin.img_SDATE_onclick = function() {
    popUpCalendar2(edt_SDATE);
};
scwin.img_EDATE_onclick = function() {
    popUpCalendar2(edt_EDATE);
};
scwin.btn_search_onclick = function() {
    scwin.ins_search();
};
scwin.cmb_PROD_GRP_KOR_NM_OnSelChange = function() {
    scwin.ins_search();
};
scwin.cmb_HALT_YN_OnSelChange = function() {
    scwin.ins_search();
};
scwin.txb_pISU_CD_onkeyup = function() {
    fn_DelChar(this);
    if (txb_pISU_CD.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
scwin.txb_pISU_KOR_ABBRV_onkeyup = function() {
    fn_DelChar3(this);
    if (txb_pISU_KOR_ABBRV.getValue() == "") {

    } else {
        if (window.event.keyCode == 13) {
            scwin.ins_search();
        } else {

        }
    }
};
